from decimal import Decimal
from typing import Any


def _numeric_value(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, str) and value.strip() == "":
        return Decimal("0")
    return Decimal(str(value))


def _account_credit_hold(record: dict, tables: dict) -> Any:
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    result_record = dict(record)

    if state == "E" and event == "approve":
        if _numeric_value(record.get("TOT_AMT", "")) > 0:
            return {
                "state": "A",
                "record": result_record,
                "audits": ["ORD_APPR"],
                "notifies": [],
                "matched": True,
            }

    elif state == "A" and event == "ship":
        return {
            "state": "S",
            "record": result_record,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    elif state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": result_record,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    elif state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    elif state == "A" and event == "cancel":
        if _account_credit_hold(record, tables) != "Y":
            return {
                "state": "X",
                "record": result_record,
                "audits": ["ORD_CANC"],
                "notifies": [],
                "matched": True,
            }

    elif state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
